SELECT
, clcid.id AS detailId, clcid.source_field AS sourceField, clcid.source_detail_field AS sourceDetailField, clcid.is_unique_key AS isUniqueKey, clcid.is_absolute_value AS isAbsoluteValue, clcid.target_field_id AS targetFieldId, clcid.target_field AS targetField, clcid.target_field_name AS targetFieldName, clcid.target_field_type AS targetFieldType, clcid.target_detail_field_id AS targetDetailFieldId, clcid.target_detail_field AS targetDetailField, clcid.target_detail_field_name AS targetDetailFieldName FROM cfg_logistics_cost_import AS clci LEFT JOIN cfg_logistics_cost_import_detail AS clcid ON clci.ID = clcid.main_id AND clcid.is_deleted = FALSE WHERE ${params.sqlMap.default} and clci.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
clci.create_time desc

SELECT disabled AS tabFlag, count(*) AS count FROM cfg_logistics_cost_import WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY disabled
